def p(t): D.add_paragraph(t)
def h(t): D.add_heading(t,2)
def step(n,t): p(f'{n}. {t}')
def code(t):
 q=D.add_paragraph(); q.paragraph_format.space_after=Pt(8)
 for i,line in enumerate(t.splitlines()):
  r=q.add_run(('\n' if i else '')+line); r.font.name='Courier New'; r.font.size=Pt(9)
def page(title):
 q=D.add_heading(title,1); q.paragraph_format.page_break_before=True
def table(head,rows,widths):
 t=D.add_table(rows=1, cols=len(head)); t.autofit=False
 for c,w in zip(t.columns,widths): c.width=Inches(w)
 for c,txt in zip(t.rows[0].cells,head): c.text=txt
 for row in rows:
  for c,txt in zip(t.add_row().cells,row): c.text=txt
 for i,row in enumerate(t.rows):
  for c,w in zip(row.cells,widths):
   c.width=Inches(w); pr=c._tc.get_or_add_tcPr(); borders=OxmlElement('w:tcBorders')
   for edge in ['top','left','bottom','right']:
    el=OxmlElement('w:'+edge); el.set(qn('w:val'),'single'); el.set(qn('w:sz'),'4'); el.set(qn('w:color'),'D9D9D9'); borders.append(el)
   pr.append(borders)
   margins=OxmlElement('w:tcMar')
   for edge in ['top','left','bottom','right']:
    el=OxmlElement('w:'+edge); el.set(qn('w:w'),'90'); el.set(qn('w:type'),'dxa'); margins.append(el)
   pr.append(margins)
   if i==0:
    sh=OxmlElement('w:shd'); sh.set(qn('w:fill'),'E7EEF5'); pr.append(sh)
   for q in c.paragraphs:
    q.paragraph_format.space_after=Pt(2); q.paragraph_format.space_before=Pt(2)
    for r in q.runs: r.font.size=Pt(10); r.bold=i==0
  tr=row._tr.get_or_add_trPr(); cant=OxmlElement('w:cantSplit'); tr.append(cant)
 rep=OxmlElement('w:tblHeader'); t.rows[0]._tr.get_or_add_trPr().append(rep)
 D.add_paragraph().paragraph_format.space_after=Pt(0)
 return t
